      "content": "import { expect, test } from 'bun:test';
import { resolve } from 'node:path';
import type { UseCase } from '@agentic-ddd/core';
import type { ClassRef } from '@agentic-ddd/decorators';
import { InMemoryEventBus, OperatorRuntime } from '@agentic-ddd/runtime';
import { covers, FakeLlm } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { CreateTask } from '../application/create-task';
import { TaskCompleted, TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';

async function fixture(llm: FakeLlm) {
  const repository = new InMemoryTaskRepository();
  const eventBus = new InMemoryEventBus();
  const runtime = new OperatorRuntime({
    llm,
    eventBus,
    root: resolve(import.meta.dir, '../..'),
    modules: [{ name: 'tasks', path: 'app' }],
  });
  await runtime.register(TaskOperator, new Map<ClassRef, UseCase<unknown, unknown>>([
    [CreateTask, new CreateTask(repository)],
    [CompleteTask, new CompleteTask(repository)],
  ]));
  return { repository, eventBus, runtime };
}

test(covers([
  'operator:task-operator',
  'criterion:0001/tools',
], 'cria e conclui uma tarefa pelas duas tools e publica TaskCreated e TaskCompleted'), async () => {
  const response = 'A tarefa t1 foi criada e concluída.';
  const llm = new FakeLlm([
    {
      stopReason: 'tool_calls',
      content: [{ type: 'tool_call', id: 'create-1', name: 'create_task', input: { task_id: 't1', title: '  Fazer tarefa  ' } }],
    },
    {
      stopReason: 'tool_calls',
      content: [{ type: 'tool_call', id: 'complete-1', name: 'complete_task', input: { task_id: 't1' } }],
    },
    { stopReason: 'end', content: [{ type: 'text', text: response }] },
  ]);
  const { repository, eventBus, runtime } = await fixture(llm);
  const publishedStates: (string | undefined)[] = [];
  eventBus.subscribe(async () => {
    publishedStates.push((await repository.findById('t1'))?.status);
  });
  expect(await repository.findById('t1')).toBeNull();

  const result = await runtime.run('task-operator', {
    message: 'Crie a tarefa t1 com título Fazer tarefa e depois conclua a tarefa t1.',
  });

  expect(result.status).toBe('completed');
  expect(result.operator).toBe('task-operator');
  expect(result.output).toBe(response);
  expect(llm.requests).toHaveLength(3);
  for (const request of llm.requests) {
    expect(request.tools.map(tool => tool.name).sort()).toEqual(['complete_task', 'create_task']);
    expect(request.system).toContain('Identifique a tarefa pelo id e responda em português.');
  }
  const tools = result.steps.flatMap(step => step.tools);
  expect(tools.map(tool => tool.call.name)).toEqual(['create_task', 'complete_task']);
  expect(tools.map(tool => tool.result)).toEqual([
    {
      toolCallId: 'create-1', isError: false,
      content: {
        output: { task_id: 't1', title: 'Fazer tarefa', status: 'pending' },
        events: [{ name: 'TaskCreated', payload: { taskId: 't1', title: 'Fazer tarefa' } }],
      },
    },
    {
      toolCallId: 'complete-1', isError: false,
      content: {
        output: { task_id: 't1', status: 'completed' },
        events: [{ name: 'TaskCompleted', payload: { taskId: 't1' } }],
      },
    },
  ]);
  expect(llm.requests[1]!.messages.at(-1)).toEqual({ role: 'tool', results: [tools[0]!.result!] });
  expect(llm.requests[2]!.messages.at(-1)).toEqual({ role: 'tool', results: [tools[1]!.result!] });
  const stored = await repository.findById('t1');
  expect(stored?.id).toBe('t1');
  expect(stored?.title).toBe('Fazer tarefa');
  expect(stored?.status).toBe('completed');
  expect(stored?.pullEvents()).toEqual([]);
  expect(publishedStates).toEqual(['pending', 'completed']);
  expect(eventBus.events).toHaveLength(2);
  expect(eventBus.events[0]).toBeInstanceOf(TaskCreated);
  expect(eventBus.events[0]!.payload).toEqual({ taskId: 't1', title: 'Fazer tarefa' });
  expect(eventBus.events[1]).toBeInstanceOf(TaskCompleted);
  expect(eventBus.events[1]!.payload).toEqual({ taskId: 't1' });
  expect(result.events).toEqual(eventBus.events);
});

