      stopReason: 'tool_calls',
      content: [{ type: 'tool_call', id: 'delete-1', name: 'delete_task', input: { task_id: 't1' } }],
    },
    { stopReason: 'end', content: [{ type: 'text', text: 'Essa operação não está disponível.' }] },
  ]);
  const { repository, eventBus, runtime } = await fixture(llm);

  const result = await runtime.run('task-operator', { message: 'Exclua a tarefa t1.' });

  expect(result.status).toBe('completed');
  expect(llm.requests).toHaveLength(2);
  expect(llm.requests[1]!.messages.at(-1)).toEqual({
    role: 'tool',
    results: [{ toolCallId: 'delete-1', isError: true, content: { code: 'unknown_tool', name: 'delete_task' } }],
  });
  expect(await repository.findById('t1')).toBeNull();
  expect(result.events).toEqual([]);
  expect(eventBus.events).toEqual([]);
